<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();
$role=(string)$_SESSION['role'];$uid=(int)$_SESSION['user_id'];$roles=['admin','director','sub_director','headteacher','head_academic','assistant_academic','examination_officer','teacher'];if(!in_array($role,$roles,true)){http_response_code(403);exit('Your role cannot access academic reports.');}
$q=db()->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();$schoolIds=array_map('intval',array_column($schools,'id'));if(!$schoolIds){http_response_code(403);exit('No school is linked to your account.');}$school=(int)($_GET['school_id']??$schoolIds[0]);if(!in_array($school,$schoolIds,true)){http_response_code(403);exit('That school is outside your access.');}
$sql="SELECT x.id,x.school_id,x.class_id,x.subject_id,x.name,x.academic_year,x.term,x.exam_date,c.name class_name,cs.name subject_name FROM school_exams x LEFT JOIN school_classes c ON c.id=x.class_id AND c.school_id=x.school_id LEFT JOIN school_class_subjects cs ON cs.id=x.subject_id AND cs.class_id=x.class_id WHERE x.school_id=? AND x.status='results_published'";$params=[$school];if($role==='teacher'){$sql.=" AND (EXISTS(SELECT 1 FROM teacher_assignments a WHERE a.user_id=? AND a.school_id=x.school_id AND a.active=1 AND a.class_level=c.name AND a.subject=cs.name) OR EXISTS(SELECT 1 FROM result_delegations d WHERE d.user_id=? AND d.school_id=x.school_id AND d.active=1 AND d.academic_year=x.academic_year AND (d.class_level IS NULL OR d.class_level=c.name)))";$params[]=$uid;$params[]=$uid;}$sql.=' ORDER BY x.academic_year DESC,x.exam_date DESC,x.id DESC LIMIT 300';$q=db()->prepare($sql);$q->execute($params);$exams=$q->fetchAll();$examId=(int)($_GET['exam_id']??0);$exam=null;foreach($exams as $candidate)if((int)$candidate['id']===$examId){$exam=$candidate;break;}if($examId&&!$exam){http_response_code(404);exit('Published examination not found in your access scope.');}if(!$exam&&$exams)$exam=$exams[0];
$assessments=[];$rows=[];$previous=null;$priorRows=[];$selectedAssessment=trim((string)($_GET['assessment']??''));$streams=[];$percentages=[];$mean=0.0;$highest=null;$lowest=null;
if($exam&&$exam['class_name']&&$exam['subject_name']){$q=db()->prepare('SELECT DISTINCT assessment FROM pupil_results WHERE school_id=? AND exam_name=? AND academic_year=? AND class_level=? AND subject=? ORDER BY assessment');$q->execute([$school,$exam['name'],$exam['academic_year'],$exam['class_name'],$exam['subject_name']]);$assessments=$q->fetchAll(PDO::FETCH_COLUMN);if($selectedAssessment&&!in_array($selectedAssessment,$assessments,true))$selectedAssessment='';if(!$selectedAssessment&&$assessments)$selectedAssessment=(string)$assessments[0];$idx=null;foreach($exams as $i=>$candidate)if((int)$candidate['id']===(int)$exam['id']){$idx=$i;break;}if($idx!==null)for($i=$idx+1;$i<count($exams);$i++)if((int)$exams[$i]['class_id']===(int)$exam['class_id']&&(int)$exams[$i]['subject_id']===(int)$exam['subject_id']){$previous=$exams[$i];break;}
 if($selectedAssessment){$q=db()->prepare('SELECT r.pupil_id,r.stream,r.score,r.max_score,r.assessment,p.admission_number,p.first_name,p.middle_name,p.last_name FROM pupil_results r JOIN pupils p ON p.id=r.pupil_id AND p.school_id=r.school_id WHERE r.school_id=? AND r.exam_name=? AND r.academic_year=? AND r.class_level=? AND r.subject=? AND r.assessment=? ORDER BY r.stream,p.last_name,p.first_name');$q->execute([$school,$exam['name'],$exam['academic_year'],$exam['class_name'],$exam['subject_name'],$selectedAssessment]);$rows=$q->fetchAll();foreach($rows as &$row){$row['percentage']=(float)$row['max_score']>0?100*(float)$row['score']/(float)$row['max_score']:0;$percentages[]=$row['percentage'];$streamName=$row['stream']?:'No stream';$streams[$streamName][]=$row['percentage'];}unset($row);if($percentages){$mean=array_sum($percentages)/count($percentages);$highest=max($percentages);$lowest=min($percentages);}
 if($previous){$q=db()->prepare('SELECT r.pupil_id,r.score,r.max_score FROM pupil_results r JOIN pupils p ON p.id=r.pupil_id AND p.school_id=r.school_id WHERE r.school_id=? AND r.exam_name=? AND r.academic_year=? AND r.class_level=? AND r.subject=? AND r.assessment=?');$q->execute([$school,$previous['name'],$previous['academic_year'],$exam['class_name'],$exam['subject_name'],$selectedAssessment]);foreach($q->fetchAll() as $pr)$priorRows[(int)$pr['pupil_id']]=(float)$pr['max_score']>0?100*(float)$pr['score']/(float)$pr['max_score']:0;}
 }}
$gradeBands=[];$gradeScaleName=null;if($exam&&$exam['class_id']){$gq=db()->prepare("SELECT id,name FROM school_grading_scales WHERE school_id=? AND academic_year=? AND status='published' AND (class_id=? OR class_id IS NULL) ORDER BY (class_id IS NULL),published_at DESC,id DESC LIMIT 1");$gq->execute([$school,(int)$exam['academic_year'],(int)$exam['class_id']]);$gs=$gq->fetch();if($gs){$gradeScaleName=(string)$gs['name'];$gq=db()->prepare("SELECT label,minimum_percent,maximum_percent FROM school_grading_bands WHERE scale_id=? ORDER BY minimum_percent");$gq->execute([(int)$gs['id']]);$gradeBands=$gq->fetchAll();}}$gradeCounts=[];foreach($gradeBands as $band)$gradeCounts[(string)$band['label']]=0;foreach($rows as $row){$pct=round((float)$row['percentage'],2);$label=null;foreach($gradeBands as $band)if($pct>=(float)$band['minimum_percent']&&$pct<=(float)$band['maximum_percent']){$label=(string)$band['label'];break;}$gradeCounts[$label??'Ungraded']=($gradeCounts[$label??'Ungraded']??0)+1;}if(!$gradeBands&&$rows)$gradeCounts=['Ungraded'=>count($rows)];$termAnalysis=[];if($exam&&$selectedAssessment&&$exam['class_id']&&$exam['subject_id']){$q=db()->prepare("SELECT x.id,x.name,x.exam_date,COUNT(r.pupil_id) assessed_pupils,AVG(100*r.score/NULLIF(r.max_score,0)) average_percent FROM school_exams x JOIN school_classes c ON c.id=x.class_id AND c.school_id=x.school_id JOIN school_class_subjects cs ON cs.id=x.subject_id AND cs.class_id=c.id JOIN pupil_results r ON r.school_id=x.school_id AND r.exam_name=x.name AND r.academic_year=x.academic_year AND r.class_level=c.name AND r.subject=cs.name AND r.assessment=? WHERE x.school_id=? AND x.class_id=? AND x.subject_id=? AND x.academic_year=? AND x.term=? AND x.status='results_published' GROUP BY x.id,x.name,x.exam_date ORDER BY x.exam_date,x.id");$q->execute([$selectedAssessment,$school,(int)$exam['class_id'],(int)$exam['subject_id'],(int)$exam['academic_year'],$exam['term']]);$termAnalysis=$q->fetchAll();}$schoolName='School';foreach($schools as $s)if((int)$s['id']===$school)$schoolName=$s['name'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Academic reports · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><style>@media print{.sidebar,.topbar,.report-controls,.page-footer{display:none!important}.app-shell,.main-area,.page-content{display:block!important;margin:0!important;padding:0!important;max-width:none!important}.content-section,.metric-card{break-inside:avoid;box-shadow:none!important}}</style><script defer src="assets/app.js"></script><script defer src="assets/academic-reports.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Workspace <span>/</span> Academic reports</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">PUBLISHED RESULTS</div><h1>Academic reports</h1><p class="muted"><?=e($schoolName)?> · Published exam results for authorized classes and subjects.</p></div><button class="button report-controls" type="button" onclick="window.print()">Print report</button></section><section class="note-create report-controls"><form method="get" class="form-grid" data-report-filter data-initial-school="<?=$school?>"><?php if(count($schools)>1):?><div><label for="report-school">School</label><select id="report-school" name="school_id"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$school?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><?php else:?><input type="hidden" name="school_id" value="<?=$school?>"><?php endif;?><div><label for="report-exam">Published examination</label><select id="report-exam" name="exam_id" required><?php foreach($exams as $x):?><option value="<?=$x['id']?>"<?=(int)($exam['id']??0)===(int)$x['id']?' selected':''?>><?=e($x['name'].' · '.$x['class_name'].' · '.$x['subject_name'].' · '.$x['academic_year'])?></option><?php endforeach;?></select></div><div><label for="report-assessment">Assessment</label><select id="report-assessment" name="assessment"><?php foreach($assessments as $a):?><option value="<?=e($a)?>"<?=$selectedAssessment===$a?' selected':''?>><?=e($a)?></option><?php endforeach;?></select></div><button class="button primary" type="submit">View report</button></form></section><?php if(!$exam):?><div class="empty-state"><h2>No published examinations</h2><p>Published results will appear here when available in your school scope.</p></div><?php else:?><section class="content-section"><div class="section-heading"><div><div class="eyebrow"><?=e($exam['class_name']??'Class')?> · <?=e($exam['subject_name']??'Subject')?></div><h2><?=e($exam['name'])?></h2><p class="muted"><?=e((string)$exam['academic_year'].' · '.($exam['term']??'').' · '.($exam['exam_date']??''))?> · <?=e($selectedAssessment)?></p></div><span class="count-pill">Published</span></div><?php if(!$rows):?><div class="empty-state"><h3>No scores found</h3><p>No score records were found for this published assessment.</p></div><?php else:?><div class="metric-grid"><article class="metric-card"><div class="metric-label">ASSESSED PUPILS</div><div class="metric-value"><?=count($rows)?></div><div class="metric-note">Recorded scores</div></article><article class="metric-card"><div class="metric-label">AVERAGE</div><div class="metric-value"><?=number_format($mean,1)?>%</div><div class="metric-note">Mean normalized score</div></article><article class="metric-card"><div class="metric-label">HIGHEST</div><div class="metric-value"><?=number_format((float)$highest,1)?>%</div><div class="metric-note">Normalized score</div></article><article class="metric-card"><div class="metric-label">LOWEST</div><div class="metric-value"><?=number_format((float)$lowest,1)?>%</div><div class="metric-note">Normalized score</div></article></div><div class="section-heading"><h3>Stream averages</h3></div><div class="table-wrap"><table><thead><tr><th>Stream</th><th>Pupils assessed</th><th>Average normalized score</th></tr></thead><tbody><?php foreach($streams as $name=>$values):?><tr><td><?=e($name)?></td><td><?=count($values)?></td><td><?=number_format(array_sum($values)/count($values),1)?>%</td></tr><?php endforeach;?></tbody></table></div><?php if($previous):?><div class="section-heading"><div><h3>Comparison with previous published exam</h3><p class="muted"><?=e($previous['name'].' · '.$previous['academic_year'])?></p></div></div><?php if($priorRows):$prevMean=array_sum($priorRows)/count($priorRows);$change=$mean-$prevMean;?><p>Previous average: <strong><?=number_format($prevMean,1)?>%</strong> · Change: <strong><?=($change>0?'+':'').number_format($change,1)?> percentage points</strong> (matching assessment label).</p><?php else:?><p class="muted">No matching assessment scores were recorded in the previous published exam.</p><?php endif;?><?php endif;?><div class="section-heading"><h3>Grade distribution</h3></div><div class="table-wrap"><table><thead><tr><th>Configured grade</th><th>Pupils</th></tr></thead><tbody><?php foreach($gradeCounts as $label=>$count):?><tr><td><?=e($label)?></td><td><?=$count?></td></tr><?php endforeach;?><?php if(!$gradeCounts):?><tr><td colspan="2">No published grading scale is configured.</td></tr><?php endif;?></tbody></table></div><div class="section-heading"><div><h3>Term assessment trend</h3><p class="muted">Same assessment label across published examinations for this class, subject, academic year, and term.</p></div></div><?php if($termAnalysis):?><div class="table-wrap"><table><thead><tr><th>Examination</th><th>Date</th><th>Pupils</th><th>Average normalized score</th></tr></thead><tbody><?php foreach($termAnalysis as $trend):?><tr><td><?=e($trend['name'])?></td><td><?=e($trend['exam_date']?:'—')?></td><td><?=(int)$trend['assessed_pupils']?></td><td><?=number_format((float)$trend['average_percent'],1)?>%</td></tr><?php endforeach;?></tbody></table></div><?php else:?><p class="muted">No published exams with this assessment label are available for the selected term.</p><?php endif;?><div class="section-heading"><div><h3>Pupil results</h3><p class="muted">Grade scale: <?=e($gradeScaleName??'No published scale')?> · Scores outside configured ranges appear as ungraded.</p></div></div><div class="table-wrap"><table><thead><tr><th>Pupil</th><th>Admission no.</th><th>Score</th><th>Normalized</th><th>Grade</th><?php if($previous):?><th>Previous</th><th>Change</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):$pct=round((float)$r['percentage'],2);$prev=$priorRows[(int)$r['pupil_id']]??null;?><tr><td><?=e(trim($r['first_name'].' '.$r['middle_name'].' '.$r['last_name']))?></td><td><?=e($r['admission_number'])?></td><td><?=number_format((float)$r['score'],2)?> / <?=number_format((float)$r['max_score'],2)?></td><td><?=number_format($pct,1)?>%</td><td><?php $grade=null;foreach($gradeBands as $band)if($pct>=(float)$band['minimum_percent']&&$pct<=(float)$band['maximum_percent']){$grade=$band['label'];break;}?><?=e($grade??'Ungraded')?></td><?php if($previous):?><td><?=$prev===null?'—':number_format($prev,1).'%'?></td><td><?=$prev===null?'—':(($pct-$prev>0?'+':'').number_format($pct-$prev,1).' pp')?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?><footer class="page-footer">ShuleLite <span>·</span> Academic reports</footer></div></main></div></body></html>
